/**
 * Testes E2E para os fluxos da página de alimentação
 * Utilizando ferramentas Supabase MCP para ambiente isolado
 */

const { 
  setupTestEnvironment, 
  applyTestMigration, 
  executeSQL, 
  cleanupTestEnvironment 
} = require('../../../e2e/config/supabase-mcp-config');

const {
  setupAlimentacaoTestEnv,
  criarPlanoRefeicaoTeste,
  criarRegistroRefeicaoTeste,
  configurarLembreteHidratacaoTeste,
  limparDadosAlimentacaoTeste,
  alimentacaoTestSchema,
  testUser
} = require('../setup-alimentacao');

// Funções auxiliares simulando autenticação e interação com a página
async function loginTestUser(page, supabase) {
  // Simula login de usuário para testes
  await page.goto('/login');
  await page.fill('[data-testid="email-input"]', testUser.email);
  await page.fill('[data-testid="password-input"]', testUser.password);
  await page.click('[data-testid="login-button"]');
  await page.waitForURL('/');
  
  // Obter ID do usuário logado
  const { data } = await supabase.auth.getUser();
  return data.user;
}

describe('Testes E2E da Página de Alimentação', () => {
  let testEnv;
  let browser;
  let page;
  let supabase;
  let testUserId;
  
  // Setup global: criar ambiente isolado para testes
  beforeAll(async () => {
    // Configurar ambiente MCP isolado para testes
    testEnv = await setupAlimentacaoTestEnv();
    
    // Inicializar navegador e página para testes
    browser = await playwright.chromium.launch();
    const context = await browser.newContext();
    page = await context.newPage();
    
    // Inicializar Supabase com chaves do ambiente de teste
    const { createClient } = require('@supabase/supabase-js');
    const { data: projectUrl } = await mcp4_get_project_url({ project_id: testEnv.projectId });
    const { data: anonKey } = await mcp4_get_anon_key({ project_id: testEnv.projectId });
    
    supabase = createClient(projectUrl, anonKey);
    
    // Registrar usuário de teste se não existir
    try {
      const { data, error } = await supabase.auth.signUp({
        email: testUser.email,
        password: testUser.password,
        options: {
          data: {
            full_name: testUser.nome_completo
          }
        }
      });
      
      if (!error) {
        testUserId = data.user.id;
      } else {
        // Tentar login se usuário já existir
        const { data: loginData } = await supabase.auth.signInWithPassword({
          email: testUser.email,
          password: testUser.password
        });
        testUserId = loginData.user.id;
      }
      
      console.log(`👤 Usuário de teste configurado: ${testUserId}`);
    } catch (error) {
      console.error('❌ Erro ao configurar usuário de teste:', error);
    }
  });
  
  // Cleanup após todos os testes
  afterAll(async () => {
    // Fechar navegador
    if (browser) {
      await browser.close();
    }
    
    // Limpar dados de teste
    if (testEnv && testEnv.success && testUserId) {
      await limparDadosAlimentacaoTeste(testEnv.projectId, testUserId);
    }
    
    // Limpar ambiente MCP
    if (testEnv && testEnv.success) {
      await cleanupTestEnvironment({
        projectId: testEnv.projectId,
        branchId: testEnv.branchId,
        isBranch: testEnv.isBranch
      });
      
      console.log('🧹 Ambiente de teste limpo com sucesso');
    }
  });
  
  // Teste: Planejamento de Refeições
  test('Deve permitir criar e visualizar um plano de refeições', async () => {
    // Pular teste se ambiente não estiver configurado
    if (!testEnv || !testEnv.success) {
      console.warn('⚠️ Ambiente de teste não configurado. Pulando teste.');
      return;
    }
    
    // 1. Fazer login com usuário de teste
    await loginTestUser(page, supabase);
    
    // 2. Visitar a página de alimentação
    await page.goto('/alimentacao');
    
    // 3. Interagir com o componente de planejamento
    await page.click('[data-testid="planejador-refeicoes-btn"]');
    await page.fill('[data-testid="meal-description"]', 'Salada com frango grelhado');
    await page.selectOption('[data-testid="meal-type"]', 'Almoço');
    await page.click('[data-testid="save-meal-plan"]');
    
    // 4. Verificar persistência no banco usando MCP
    const result = await executeSQL(
      testEnv.projectId,
      `SELECT * FROM meal_plans WHERE user_id = '${testUserId}' ORDER BY created_at DESC LIMIT 1`
    );
    
    // 5. Validar resultados
    expect(result.success).toBe(true);
    expect(result.data.length).toBeGreaterThan(0);
    expect(result.data[0].description).toBe('Salada com frango grelhado');
    expect(result.data[0].meal_type).toBe('Almoço');
    
    // 6. Verificar exibição na UI
    await page.reload();
    const mealPlanElement = await page.waitForSelector('[data-testid="meal-plan-item"]');
    const mealPlanText = await mealPlanElement.textContent();
    expect(mealPlanText).toContain('Salada com frango grelhado');
  });

  // Teste: Registro de Refeições
  test('Deve permitir registrar uma refeição consumida', async () => {
    // Pular teste se ambiente não estiver configurado
    if (!testEnv || !testEnv.success) {
      console.warn('⚠️ Ambiente de teste não configurado. Pulando teste.');
      return;
    }
    
    // 1. Fazer login com usuário de teste
    await loginTestUser(page, supabase);
    
    // 2. Visitar a página de alimentação
    await page.goto('/alimentacao');
    
    // 3. Interagir com o componente de registro
    await page.click('[data-testid="registro-refeicoes-btn"]');
    await page.fill('[data-testid="meal-record-description"]', 'Café da manhã: Aveia com frutas');
    await page.fill('[data-testid="meal-record-calories"]', '350');
    await page.click('[data-testid="save-meal-record"]');
    
    // 4. Verificar persistência no banco usando MCP
    const result = await executeSQL(
      testEnv.projectId,
      `SELECT * FROM meal_records WHERE user_id = '${testUserId}' ORDER BY created_at DESC LIMIT 1`
    );
    
    // 5. Validar resultados
    expect(result.success).toBe(true);
    expect(result.data.length).toBeGreaterThan(0);
    expect(result.data[0].description).toContain('Café da manhã');
    expect(result.data[0].calories).toBe(350);
    
    // 6. Verificar exibição na UI
    await page.reload();
    const mealRecordElement = await page.waitForSelector('[data-testid="meal-record-item"]');
    const mealRecordText = await mealRecordElement.textContent();
    expect(mealRecordText).toContain('Aveia com frutas');
  });

  // Teste: Lembretes de Hidratação
  test('Deve permitir configurar lembretes de hidratação', async () => {
    // Pular teste se ambiente não estiver configurado
    if (!testEnv || !testEnv.success) {
      console.warn('⚠️ Ambiente de teste não configurado. Pulando teste.');
      return;
    }
    
    // 1. Fazer login com usuário de teste
    await loginTestUser(page, supabase);
    
    // 2. Visitar a página de alimentação
    await page.goto('/alimentacao');
    
    // 3. Interagir com o componente de lembrete
    await page.click('[data-testid="lembrete-hidratacao-btn"]');
    await page.check('[data-testid="hydration-active"]');
    await page.fill('[data-testid="hydration-frequency"]', '45');
    await page.fill('[data-testid="hydration-start-time"]', '07:00');
    await page.fill('[data-testid="hydration-end-time"]', '21:00');
    await page.click('[data-testid="save-hydration-config"]');
    
    // 4. Verificar persistência no banco usando MCP
    const result = await executeSQL(
      testEnv.projectId,
      `SELECT * FROM hydration_reminders WHERE user_id = '${testUserId}' ORDER BY created_at DESC LIMIT 1`
    );
    
    // 5. Validar resultados
    expect(result.success).toBe(true);
    expect(result.data.length).toBeGreaterThan(0);
    expect(result.data[0].active).toBe(true);
    expect(result.data[0].frequency_minutes).toBe(45);
    expect(result.data[0].start_time).toBe('07:00:00');
    expect(result.data[0].end_time).toBe('21:00:00');
    
    // 6. Verificar exibição na UI
    await page.reload();
    const reminderElement = await page.waitForSelector('[data-testid="hydration-reminder-status"]');
    const reminderText = await reminderElement.textContent();
    expect(reminderText).toContain('Ativo');
  });

  // Teste: Navegação para Receitas
  test('Deve navegar para a página de receitas', async () => {
    // Pular teste se ambiente não estiver configurado
    if (!testEnv || !testEnv.success) {
      console.warn('⚠️ Ambiente de teste não configurado. Pulando teste.');
      return;
    }
    
    // 1. Fazer login com usuário de teste
    await loginTestUser(page, supabase);
    
    // 2. Visitar a página de alimentação
    await page.goto('/alimentacao');
    
    // 3. Clicar no link para receitas
    await page.click('[data-testid="receitas-link"]');
    
    // 4. Verificar se a navegação ocorreu corretamente
    await page.waitForURL('/receitas');
    expect(page.url()).toContain('/receitas');
  });
});
